import pathlib,json,hashlib,collections,numpy as np,ast
R=pathlib.Path(r'C:\tmp\disdex-d126-crossrunner-research-20261126')
P=R/'Y06_R18_PORTFOLIO_REPAIR_PROTOCOL_20261127.json';O=R/'Y06_R18_PORTFOLIO_REPAIR_RESULTS_20261127.json'
assert not P.exists() and not O.exists()
parent=R/'y06_r17_old_new_portfolio_20261127.py'
p={'status':'RESEARCH_ONLY_NO_LIVE','parent_sha256':hashlib.sha256(parent.read_bytes()).hexdigest(),'scope':'Same R17 common period, initial10000, gross0.30 per entry, two slots, 12h cooldown, 10/30bps. All source periods previously inspected.','old_gates':['NONE','NO_BULL','NO_STRETCH','NO_BULL_STRETCH','NO_BULL_BTC3UP','NO_BULL_STRETCH_BTC3UP'],'gate_definition':'Completed H1 BTC24/72 both positive veto; 3h asset decline >2 prior ATR veto; BTC3h positive veto. Fixed thresholds from diagnostic, no forward price input.','allocation':['FIFO','RESERVE_NEW'],'reserve':'At most one simultaneous OLD24, NEW48 may use two slots, no forced exit, no additional gross.','exit':['BASE','NEW_TRAIL','BOTH_TRAIL'],'trail':'Keep original STOP8 and TP8 if NEW, and native H24/H48. Only after completed M5 low indicates >=2% favorable excursion, stop at prior running low*1.015; check open gap then intrabar STOP before target, update running low after bar. No same-bar activation. No funding.','comparison':'36 fixed arms + same-tape standalones. Record actual route PnL and blocks. No adoption without independent/stress verification.'}
P.write_text(json.dumps(p,indent=2),encoding='utf8')
s=parent.read_text()
prefix=s[:s.index("P=R/")]+s[s.index("old=R/"):s.index("p={'status'")]+s[s.index("bt.PERIODS['FORWARD_INSPECTED']"):s.index("# Independent portfolio")]
exec(compile(prefix,'r17_replay','exec'))
# protocol variable was not overwritten by prefix
btc,_=bt.data('BTC','1h')
base={k:v for k,v in tapes.items()}
def flags(x):
 i=(x['entryTs']-bt.HS)//H;h=hs[x['symbol']]
 if i<73 or not np.isfinite(btc[i-73:i,3]).all() or not np.isfinite(h[i-25:i,:4]).all():return None
 atr=r3.calc_atr(h,i)
 if not atr or atr<=0:return None
 bull=btc[i-1,3]>btc[i-25,3] and btc[i-1,3]>btc[i-73,3]
 up=btc[i-1,3]>btc[i-4,3]
 stretch=(h[i-4,3]-h[i-1,3])/atr>2
 return {'NONE':True,'NO_BULL':not bull,'NO_STRETCH':not stretch,'NO_BULL_STRETCH':not(bull or stretch),'NO_BULL_BTC3UP':not(bull or up),'NO_BULL_STRETCH_BTC3UP':not(bull or stretch or up)}
def trailing(x):
 t=x['entryTs'];m=ms[x['symbol']];k=(t-bt.MS)//M;hr=24 if x['route']=='OLD24' else 48;j=k+hr*12
 if j>=len(m) or not np.isfinite(m[k:j+1,:4]).all():return None
 ep=float(m[k,0]);best=ep;target=ep*.92 if x['route']=='NEW48' else None
 xp=float(m[j,0]);et=bt.MS+j*M;reason='TIME'+str(hr)
 for q in range(k,j):
  o,hi,lo,c=m[q,:4];stop=min(ep*1.08,best*1.015) if best<=ep*.98 else ep*1.08
  if o>=stop or hi>=stop:
   xp=float(max(o,stop));et=bt.MS+(q+1)*M;reason='TRAIL_STOP' if stop<ep*1.08 else 'HARD_STOP8';break
  if target is not None and lo<=target:
   xp=float(target);et=bt.MS+(q+1)*M;reason='TARGET';break
  best=min(best,float(lo))
 return {**x,'exitTs':et,'exitPrice':xp,'rawReturn':1-xp/ep,'exitReason':reason}
def wallet2(cands,per,fee,alloc):
 begin,end=bt.PERIODS[per];eq=np.full((end-begin)//M+1,10000.);active=[];cool={};acc=[];blocked=collections.Counter()
 for x in sorted(cands,key=lambda y:(y['entryTs'],y['symbol'],y['route'])):
  t=x['entryTs'];e=x['exitTs'];s=x['symbol'];rt=x['route'];active=[a for a in active if a['exitTs']>t]
  if not(begin<=t<e<end):continue
  if len(active)>=2:blocked[rt+'_SLOTS']+=1;continue
  if any(a['symbol']==s for a in active):blocked[rt+'_SAME']+=1;continue
  if t<cool.get(s,0):blocked[rt+'_COOLDOWN']+=1;continue
  if alloc=='RESERVE_NEW' and rt=='OLD24' and any(a['route']=='OLD24' for a in active):blocked[rt+'_RESERVE']+=1;continue
  i=(t-begin)//M;j=(e-begin)//M;mi=(t-bt.MS)//M;nt=.30*eq[i];px=ms[s][mi:mi+j-i,0]
  if nt<=0 or len(px)!=j-i or not np.isfinite(px).all():continue
  eq[i:j]+=nt*(1-px/x['entry']-fee/20000);net=nt*(x['rawReturn']-fee/10000);eq[j:]+=net
  active.append(x);cool[s]=e+12*H;acc.append((rt,float(net),x))
 peak=np.maximum.accumulate(np.r_[10000.,eq])[1:];w=sum(v>0 for rt,v,x in acc);pos=sum(v for rt,v,x in acc if v>0);neg=-sum(v for rt,v,x in acc if v<0)
 return {'terminal_jpy':float(eq[-1]),'max_dd_pct':float(100*np.max(1-eq/peak)),'n':len(acc),'wins':w,'win_pct':100*w/len(acc) if acc else None,'pf':pos/neg if neg else None,'route_pnl':{k:sum(v for a,v,x in acc if a==k) for k in ('OLD24','NEW48')},'route_n':dict(collections.Counter(a for a,v,x in acc)),'blocked':dict(blocked)}
oldf=[(x,flags(x)) for x in base['OLD24']];oldf=[(x,f) for x,f in oldf if f is not None]
trail={k:[z for x in base[k] if (z:=trailing(x)) is not None] for k in ('OLD24','NEW48')}
trailmap={(x['symbol'],x['entryTs']):x for x in trail['OLD24']}
out={}
for g in p['old_gates']:
 for alloc in p['allocation']:
  for ex in p['exit']:
   oo=[x if ex!='BOTH_TRAIL' else trailmap.get((x['symbol'],x['entryTs'])) for x,f in oldf if f[g]];oo=[x for x in oo if x is not None]
   nn=base['NEW48'] if ex=='BASE' else trail['NEW48']
   key=g+'/'+alloc+'/'+ex;out[key]={}
   for per in bt.PERIODS:out[key][per]={str(f):wallet2([x for x in oo+nn if x['period']==per],per,f,alloc) for f in (10,30)}
   print('BT',key,[(round(v['10']['terminal_jpy']),round(v['30']['terminal_jpy']),round(v['30']['max_dd_pct'],2),round(v['30']['win_pct'],2),v['30']['n']) for v in out[key].values()],flush=True)
O.write_text(json.dumps({'protocol':p,'protocol_sha256':hashlib.sha256(P.read_bytes()).hexdigest(),'results':out,'old_flag_missing':len(base['OLD24'])-len(oldf)},indent=2,allow_nan=False,default=lambda x:x.item()),encoding='utf8')
print('SAVED',hashlib.sha256(O.read_bytes()).hexdigest(),flush=True)
